import * as THREE from 'three';
import fs from 'fs';
import path from 'path';
import { createScene } from './data/object.js';

// Function to convert a THREE.Geometry or BufferGeometry to OBJ format
function geometryToOBJ(geometry, matrix = new THREE.Matrix4()) {
  const positions = [];
  const normals = [];
  const faces = [];
  let vertexOffset = 0;

  // Handle BufferGeometry
  if (geometry.isBufferGeometry) {
    const positionAttribute = geometry.getAttribute('position');
    const normalAttribute = geometry.getAttribute('normal');

    if (!positionAttribute) {
      return { vertices: [], normals: [], faces: [] };
    }

    // Extract vertices and apply matrix transformation
    for (let i = 0; i < positionAttribute.count; i++) {
      const vertex = new THREE.Vector3();
      vertex.fromBufferAttribute(positionAttribute, i);
      vertex.applyMatrix4(matrix);
      positions.push(vertex);
    }

    // Extract normals if available
    if (normalAttribute) {
      for (let i = 0; i < normalAttribute.count; i++) {
        const normal = new THREE.Vector3();
        normal.fromBufferAttribute(normalAttribute, i);
        normals.push(normal);
      }
    }

    // Extract faces
    const indexAttribute = geometry.getIndex();
    if (indexAttribute) {
      for (let i = 0; i < indexAttribute.count; i += 3) {
        const a = indexAttribute.getX(i) + vertexOffset;
        const b = indexAttribute.getX(i + 1) + vertexOffset;
        const c = indexAttribute.getX(i + 2) + vertexOffset;
        faces.push([a + 1, b + 1, c + 1]); // OBJ indices are 1-based
      }
    } else {
      // No index, use sequential vertices
      for (let i = 0; i < positionAttribute.count; i += 3) {
        const a = i + vertexOffset;
        const b = i + 1 + vertexOffset;
        const c = i + 2 + vertexOffset;
        faces.push([a + 1, b + 1, c + 1]);
      }
    }
  }

  return { vertices: positions, normals: normals, faces: faces };
}

// Recursively traverse the scene and collect all meshes
function traverseScene(object, meshes = [], globalMatrix = new THREE.Matrix4()) {
  const currentMatrix = new THREE.Matrix4();
  currentMatrix.copy(globalMatrix);

  // Apply current object's transform
  const localMatrix = new THREE.Matrix4();
  localMatrix.compose(object.position, object.quaternion, object.scale);
  currentMatrix.multiplyMatrices(globalMatrix, localMatrix);

  if (object.isMesh && object.geometry) {
    meshes.push({
      name: object.name,
      geometry: object.geometry,
      matrix: currentMatrix.clone()
    });
  }

  if (object.isInstancedMesh && object.geometry) {
    // Handle InstancedMesh - extract each instance
    const temp = new THREE.Object3D();
    for (let i = 0; i < object.count; i++) {
      object.getMatrixAt(i, temp.matrix);
      const instanceMatrix = new THREE.Matrix4();
      instanceMatrix.multiplyMatrices(currentMatrix, temp.matrix);
      meshes.push({
        name: `${object.name}_instance_${i}`,
        geometry: object.geometry,
        matrix: instanceMatrix
      });
    }
  }

  for (let child of object.children) {
    traverseScene(child, meshes, currentMatrix);
  }

  return meshes;
}

// Main export function
function exportToOBJ(scene, outputPath) {
  // Create the coordinate space conversion matrix (Y-up to Z-up: -90 degree X rotation)
  const conversionMatrix = new THREE.Matrix4();
  const eulerRotation = new THREE.Euler(-Math.PI / 2, 0, 0, 'XYZ');
  const rotationQuat = new THREE.Quaternion();
  rotationQuat.setFromEuler(eulerRotation);
  conversionMatrix.compose(new THREE.Vector3(0, 0, 0), rotationQuat, new THREE.Vector3(1, 1, 1));

  // Traverse scene and collect all meshes
  const meshes = traverseScene(scene, [], new THREE.Matrix4());

  let objContent = '# Exported from Three.js\n';
  objContent += '# Original coordinate system converted to Blender Z-up\n\n';

  let vertexCount = 0;
  const allVertices = [];
  const allNormals = [];
  const allFaces = [];

  // Process each mesh
  for (const mesh of meshes) {
    // Combine transformation matrices
    const finalMatrix = new THREE.Matrix4();
    finalMatrix.multiplyMatrices(conversionMatrix, mesh.matrix);

    const data = geometryToOBJ(mesh.geometry, finalMatrix);

    if (data.vertices.length > 0) {
      objContent += `# Mesh: ${mesh.name}\n`;

      // Add vertices
      for (const vertex of data.vertices) {
        objContent += `v ${vertex.x.toFixed(6)} ${vertex.y.toFixed(6)} ${vertex.z.toFixed(6)}\n`;
        vertexCount++;
      }

      // Add normals
      for (const normal of data.normals) {
        objContent += `vn ${normal.x.toFixed(6)} ${normal.y.toFixed(6)} ${normal.z.toFixed(6)}\n`;
      }

      // Add faces
      objContent += `g ${mesh.name}\n`;
      for (const face of data.faces) {
        if (data.normals.length > 0) {
          objContent += `f ${face[0]}/${face[0]}/${face[0]} ${face[1]}/${face[1]}/${face[1]} ${face[2]}/${face[2]}/${face[2]}\n`;
        } else {
          objContent += `f ${face[0]} ${face[1]} ${face[2]}\n`;
        }
      }

      objContent += '\n';
    }
  }

  // Ensure output directory exists
  const outputDir = path.dirname(outputPath);
  if (!fs.existsSync(outputDir)) {
    fs.mkdirSync(outputDir, { recursive: true });
  }

  // Write OBJ file
  fs.writeFileSync(outputPath, objContent);
  console.log(`✓ Exported to ${outputPath}`);
  console.log(`✓ Total vertices: ${vertexCount}`);
  console.log(`✓ Coordinate system: Y-up converted to Z-up (Blender compatible)`);
}

// Execute
try {
  const scene = createScene();
  exportToOBJ(scene, '/root/output/object.obj');
} catch (error) {
  console.error('Error during export:', error);
  process.exit(1);
}

